params.command:
$ErrorActionPreference='Stop'
$roots=@()
if($env:RUNNER_TEMP -and (Test-Path -LiteralPath $env:RUNNER_TEMP)){
  $roots += Get-ChildItem -LiteralPath $env:RUNNER_TEMP -Directory -Filter 'mhw-startup-perf-*' -ErrorAction SilentlyContinue
}
$roots += Get-ChildItem -LiteralPath $env:TEMP -Directory -Filter 'mhw-startup-perf-*' -ErrorAction SilentlyContinue
$root=$roots | Sort-Object LastWriteTimeUtc -Descending | Select-Object -First 1
if(-not $root){throw 'No startup performance fixture root found'}
Write-Output ("FIXTURE_ROOT="+$root.FullName)
Get-ChildItem -LiteralPath $root.FullName -Directory | Sort-Object Name | ForEach-Object {
  Write-Output ("DIR="+$_.FullName)
  $sl=Join-Path $_.FullName 'StartupLogs'
  if(Test-Path -LiteralPath $sl){
    Get-ChildItem -LiteralPath $sl -File | Sort-Object LastWriteTimeUtc | ForEach-Object {
      Write-Output ("STARTUP_FILE="+$_.FullName+" SIZE="+$_.Length)
      if($_.Extension -in '.log','.json'){
        Write-Output '---TAIL---'
        Get-Content -LiteralPath $_.FullName -Tail 80 -ErrorAction SilentlyContinue
      }
    }
  }
  $ml=Join-Path $_.FullName 'MHW-DEBUG-ALL.log'
  if(Test-Path -LiteralPath $ml){
    Write-Output ("MASTER_LOG="+$ml)
    Get-Content -LiteralPath $ml -Tail 120
  }
}
